using static StrataLint.Scribe.DefinitionDsl;
namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Fermionic;
internal sealed class BcGhostQuartetCountDocument : IScribeDocumentDefinition
{
    private static DocumentBlock Node(string name, string prose, DescribeRole role = DescribeRole.Theorem) => Describe.Lean(
        DescribeId.Create("bc-ghost-quartet-count-" + name.Replace("_", "-").ToLowerInvariant()),
        DeclarationHandle.Create("D5/S3/Quantum/Fermionic/BcGhostQuartetCount." + name),
        H(name.Replace("_", " ")), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "The actual original bc mode sum has a natural occupation count, a spectral inverse, a two-dimensional full ground and a one-dimensional literal relative ground.",
        H("Actual ghost quartet count on the original Fock carrier"), Blocks(
                Paragraph(Text("The carrier is CountableOccupationFock.Fock: complex finitely supported functions on finite subsets of the natural sites. Ket S is the original Finsupp.single S 1; vacuum is ket of the empty set. Creators and annihilators use the original Jordan-Wigner sign, minus one to the number of occupied sites strictly below the operated site. The b and c modes are exactly BcGhostFock.b and BcGhostFock.c, with annihilation cuts b at m at least minus one and c at n at least two. No tensor decomposition, dimension bound, spectral identity, positivity premise or additional state-finiteness premise is introduced. All operator products compose right to left; natural count scalars are cast into Complex.")),
                Node("U", "For positive k this is c at minus k composed with b at k plus b at minus k composed with c at k. The artificial natural-index zero term is zero. Products act from right to left. Original Lean signature: def U (k : \u2115) : Module.End \u2102 Fock", DescribeRole.Definition),
                Node("U_zero", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: @[simp] theorem U_zero : U 0 = 0"),
                Node("U_pos", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem U_pos (k : \u2115) (hk : 0 < k) :\n    U k = c (-(k : \u2124)) * b (k : \u2124) + b (-(k : \u2124)) * c (k : \u2124)"),
                Node("phase_insert_self", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: @[simp] theorem phase_insert_self (j : \u2115) (S : Finset \u2115) :\n    phase j (insert j S) = phase j S"),
                Node("phase_erase_self", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: @[simp] theorem phase_erase_self (j : \u2115) (S : Finset \u2115) :\n    phase j (S.erase j) = phase j S"),
                Node("phase_square", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: @[simp] theorem phase_square (j : \u2115) (S : Finset \u2115) :\n    phase j S * phase j S = 1"),
                Node("create_annihilate_ket", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem create_annihilate_ket (j : \u2115) (S : Finset \u2115) :\n    (create j * annihilate j) (ket S) = if j \u2208 S then ket S else 0"),
                Node("annihilate_create_ket", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem annihilate_create_ket (j : \u2115) (S : Finset \u2115) :\n    (annihilate j * create j) (ket S) = if j \u2208 S then 0 else ket S"),
                Node("b_positive", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem b_positive (k : \u2115) : b (k : \u2124) = annihilate (2 * k + 3)"),
                Node("c_negative", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem c_negative (k : \u2115) : c (-(k : \u2124)) = create (2 * k + 3)"),
                Node("b_negative_one", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: @[simp] theorem b_negative_one : b (-1) = annihilate 1"),
                Node("c_positive_one", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: @[simp] theorem c_positive_one : c 1 = create 1"),
                Node("b_zero", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: @[simp] theorem b_zero : b 0 = annihilate 3"),
                Node("b_negative_ge_two", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem b_negative_ge_two (k : \u2115) (hk : 2 \u2264 k) :\n    b (-(k : \u2124)) = create (2 * (k - 2))"),
                Node("c_positive_ge_two", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem c_positive_ge_two (k : \u2115) (hk : 2 \u2264 k) :\n    c (k : \u2124) = annihilate (2 * (k - 2))"),
                Node("c_negative_b_positive_ket", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem c_negative_b_positive_ket (k : \u2115) (S : Finset \u2115) :\n    (c (-(k : \u2124)) * b (k : \u2124)) (ket S) =\n      if 2 * k + 3 \u2208 S then ket S else 0"),
                Node("b_negative_c_positive_ket", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem b_negative_c_positive_ket (k : \u2115) (hk : 0 < k) (S : Finset \u2115) :\n    (b (-(k : \u2124)) * c (k : \u2124)) (ket S) =\n      if k = 1 then (if 1 \u2208 S then 0 else ket S)\n      else (if 2 * (k - 2) \u2208 S then ket S else 0)"),
                Node("localCount", "The odd occupied site is 2k+3 for positive k. At k=1 the second branch counts the hole at site 1. For k at least 2 it counts the occupied even site 2(k-2). Original Lean signature: def localCount (k : \u2115) (S : Finset \u2115) : \u2115", DescribeRole.Definition),
                Node("U_ket", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem U_ket (k : \u2115) (S : Finset \u2115) :\n    U k (ket S) = (localCount k S : \u2102) \u2022 ket S"),
                Node("count", "The count is the cardinality of S with sites 1 and 3 erased, plus one precisely when site 1 is absent. Site 3 is uncounted; occupying site 1 removes a hole. Original Lean signature: def count (S : Finset \u2115) : \u2115", DescribeRole.Definition),
                Node("count_insert_regular", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem count_insert_regular (j : \u2115) (S : Finset \u2115)\n    (hj1 : j \u2260 1) (hj3 : j \u2260 3) (hj : j \u2209 S) :\n    count (insert j S) = count S + 1"),
                Node("count_erase_regular", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem count_erase_regular (j : \u2115) (S : Finset \u2115)\n    (hj1 : j \u2260 1) (hj3 : j \u2260 3) (hj : j \u2208 S) :\n    count S = count (S.erase j) + 1"),
                Node("count_insert_one", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem count_insert_one (S : Finset \u2115) (h1 : 1 \u2209 S) :\n    count (insert 1 S) + 1 = count S"),
                Node("count_erase_one", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem count_erase_one (S : Finset \u2115) (h1 : 1 \u2208 S) :\n    count (S.erase 1) = count S + 1"),
                Node("count_nonnegative", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem count_nonnegative (S : Finset \u2115) : 0 \u2264 count S"),
                Node("sum_localCount", "Explicit bijections enumerate the odd sites other than 1 and 3 and the even sites in S. Their parity partition and the exceptional hole give the count for every finite capture satisfying the displayed bounds. Original Lean signature: theorem sum_localCount (S : Finset \u2115) (N : \u2115) (hN : 3 \u2264 N)\n    (hS : \u2200 j \u2208 S, j + 3 \u2264 N) :\n    (\u2211 k \u2208 Finset.range N, localCount k S) = count S"),
                Node("localCount_zero_of_capture", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem localCount_zero_of_capture (S : Finset \u2115) (k : \u2115) (hk : 3 \u2264 k)\n    (hS : \u2200 j \u2208 S, j + 3 \u2264 k) : localCount k S = 0"),
                Node("occupied", "Take the finite union of the actual occupied site sets in the finitely supported input. Original Lean signature: def occupied (v : Fock) : Finset \u2115", DescribeRole.Definition),
                Node("capture", "The maximum occupied site plus three bounds every potentially nonzero positive summand for this actual input. Original Lean signature: def capture (v : Fock) : \u2115", DescribeRole.Definition),
                Node("site_capture", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem site_capture (v : Fock) (S : Finset \u2115) (hS : S \u2208 v.support)\n    (j : \u2115) (hj : j \u2208 S) : j + 3 \u2264 capture v"),
                Node("ket_expansion", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem ket_expansion (v : Fock) :\n    (\u2211 S \u2208 v.support, v S \u2022 ket S) = v"),
                Node("U_zero_above_capture", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem U_zero_above_capture (v : Fock) (k : \u2115) (hk : capture v \u2264 k) :\n    U k v = 0"),
                Node("mode_support_subset", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem mode_support_subset (v : Fock) :\n    Function.support (fun k => U k v) \u2286 (Finset.range (capture v) : Set \u2115)"),
                Node("mode_support_finite", "Every original finite-excitation state has a finite evaluated mode support. No finite support of the endomorphism family is asserted or assumed. Original Lean signature: theorem mode_support_finite (v : Fock) :\n    (Function.support (fun k => U k v)).Finite"),
                Node("modeSum", "This is the locally finite finsum of the original paired modes evaluated on the input. Its finiteness is proved before linearity. Original Lean signature: def modeSum (v : Fock) : Fock", DescribeRole.Definition),
                Node("modeSum_eq_sum", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem modeSum_eq_sum (v : Fock) (N : \u2115) (hN : capture v \u2264 N) :\n    modeSum v = \u2211 k \u2208 Finset.range N, U k v"),
                Node("modeSum_add", "One finite range contains the captures of v, w and v+w. Linearity of each original summand proves additivity on that common range. Original Lean signature: theorem modeSum_add (v w : Fock) : modeSum (v + w) = modeSum v + modeSum w"),
                Node("modeSum_smul", "One finite range contains the captures of v and its scalar multiple. Scalar compatibility follows on this common range. Original Lean signature: theorem modeSum_smul (a : \u2102) (v : Fock) : modeSum (a \u2022 v) = a \u2022 modeSum v"),
                Node("M", "The actual mode sum is packaged as a complex linear endomorphism only after its linearity has been proved. Original Lean signature: def M : Module.End \u2102 Fock", DescribeRole.Definition),
                Node("M_eq_modeSum", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem M_eq_modeSum (v : Fock) : M v = \u2211\u1da0 k : \u2115, U k v"),
                Node("M_eq_sum", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem M_eq_sum (v : Fock) (N : \u2115) (hN : capture v \u2264 N) :\n    M v = \u2211 k \u2208 Finset.range N, U k v"),
                Node("M_ket", "The spectrum on each original occupation ket is derived from the original b and c actions and finite enumeration, rather than supplied as a hypothesis. Original Lean signature: theorem M_ket (S : Finset \u2115) : M (ket S) = (count S : \u2102) \u2022 ket S"),
                Node("diagonal", "A coefficient multiplier on the same original Finsupp carrier is used after deriving the actual mode count. It is not a replacement Fock representation. Original Lean signature: def diagonal (f : Finset \u2115 \u2192 \u2102) : Module.End \u2102 Fock", DescribeRole.Definition),
                Node("diagonal_ket", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: @[simp] theorem diagonal_ket (f : Finset \u2115 \u2192 \u2102) (S : Finset \u2115) :\n    diagonal f (ket S) = f S \u2022 ket S"),
                Node("diagonal_coefficient", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem diagonal_coefficient (f : Finset \u2115 \u2192 \u2102) (v : Fock) (S : Finset \u2115) :\n    diagonal f v S = f S * v S"),
                Node("M_eq_diagonal", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem M_eq_diagonal : M = diagonal (fun S => (count S : \u2102))"),
                Node("M_coefficient", "For every original state and every finite occupation, the output coefficient is its input coefficient multiplied by the natural occupation count cast to Complex. Original Lean signature: theorem M_coefficient (v : Fock) (S : Finset \u2115) :\n    M v S = (count S : \u2102) * v S"),
                Node("M_support_subset", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem M_support_subset (v : Fock) : (M v).support \u2286 v.support"),
                Node("eigenvector_iff", "An eigenvector may have several nonzero coefficients; every occupation in its support must carry exactly the displayed eigenvalue. Original Lean signature: theorem eigenvector_iff (v : Fock) (z : \u2102) :\n    M v = z \u2022 v \u2194 \u2200 S \u2208 v.support, (count S : \u2102) = z"),
                Node("nonzero_eigenvalue_is_natural", "A nonzero coefficient witnesses that the eigenvalue is a natural count. Nonnegativity is algebraic here; no positive ghost inner product is claimed. Original Lean signature: theorem nonzero_eigenvalue_is_natural (v : Fock) (z : \u2102)\n    (hv : v \u2260 0) (he : M v = z \u2022 v) : \u2203 q : \u2115, z = (q : \u2102)"),
                Node("count_surjective_relative", "Every natural number is attained by an occupation omitting site 3. The construction starts at the occupied site-1 ground and inserts a fresh regular site at each successor. Original Lean signature: theorem count_surjective_relative (q : \u2115) :\n    \u2203 S : Finset \u2115, 3 \u2209 S \u2227 count S = q"),
                Node("P", "Projection onto all zero-count states of the full original carrier, including the site-3 partner. Original Lean signature: def P : Module.End \u2102 Fock", DescribeRole.Definition),
                Node("invM", "On a nonzero natural count use its complex reciprocal, and set the zero-count coefficient to zero. Original Lean signature: def invM : Module.End \u2102 Fock", DescribeRole.Definition),
                Node("P_ket", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: @[simp] theorem P_ket (S : Finset \u2115) :\n    P (ket S) = (if count S = 0 then (1 : \u2102) else 0) \u2022 ket S"),
                Node("invM_ket", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: @[simp] theorem invM_ket (S : Finset \u2115) :\n    invM (ket S) = (if count S = 0 then (0 : \u2102) else (count S : \u2102)\u207b\u00b9) \u2022 ket S"),
                Node("P_coefficient", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem P_coefficient (v : Fock) (S : Finset \u2115) :\n    P v S = if count S = 0 then v S else 0"),
                Node("invM_coefficient", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem invM_coefficient (v : Fock) (S : Finset \u2115) :\n    invM v S = if count S = 0 then 0 else (count S : \u2102)\u207b\u00b9 * v S"),
                Node("M_mul_invM", "The original count followed by its spectral inverse is identity minus the full zero-count projection. Original Lean signature: theorem M_mul_invM : M * invM = 1 - P"),
                Node("invM_mul_M", "The reverse product gives the same identity minus the full zero-count projection. Original Lean signature: theorem invM_mul_M : invM * M = 1 - P"),
                Node("P_idempotent", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem P_idempotent : P * P = P"),
                Node("P_sq", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem P_sq : P ^ 2 = P"),
                Node("M_mul_P", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem M_mul_P : M * P = 0"),
                Node("P_mul_M", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem P_mul_M : P * M = 0"),
                Node("invM_mul_P", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem invM_mul_P : invM * P = 0"),
                Node("P_mul_invM", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem P_mul_invM : P * invM = 0"),
                Node("count_zero_iff", "The complete zero-count occupation sets are precisely {1} and {1,3}. In particular the full kernel is not a single vacuum line. Original Lean signature: theorem count_zero_iff (S : Finset \u2115) :\n    count S = 0 \u2194 S = {1} \u2228 S = {1, 3}"),
                Node("P_apply", "The full projection retains exactly the two original coefficients at {1} and {1,3}. Original Lean signature: theorem P_apply (v : Fock) :\n    P v = v {1} \u2022 ket {1} + v {1, 3} \u2022 ket {1, 3}"),
                Node("M_eq_zero_iff_P_eq_self", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem M_eq_zero_iff_P_eq_self (v : Fock) : M v = 0 \u2194 P v = v"),
                Node("full_kernel_iff", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem full_kernel_iff (v : Fock) :\n    M v = 0 \u2194 \u2203 a d : \u2102, v = a \u2022 ket {1} + d \u2022 ket {1, 3}"),
                Node("full_kernel", "The full zero eigenspace is exactly the complex span of the two displayed original kets. Original Lean signature: theorem full_kernel : LinearMap.ker M =\n    Submodule.span \u2102 ({ket {1}, ket {1, 3}} : Set Fock)"),
                Node("b0_down", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: @[simp] theorem b0_down : b 0 (ket {1}) = 0"),
                Node("b0_other_ground", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: @[simp] theorem b0_other_ground : b 0 (ket {1, 3}) = -ket {1}"),
                Node("b0_eq_zero_iff_coefficients", "The literal original zero mode b at zero is annihilation at site 3. Its kernel is characterized by vanishing of every coefficient whose occupation contains site 3. Original Lean signature: theorem b0_eq_zero_iff_coefficients (v : Fock) :\n    b 0 v = 0 \u2194 \u2200 S : Finset \u2115, 3 \u2208 S \u2192 v S = 0"),
                Node("relative_kernel_iff", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem relative_kernel_iff (v : Fock) :\n    (M v = 0 \u2227 b 0 v = 0) \u2194 \u2203 a : \u2102, v = a \u2022 ket {1}"),
                Node("relative_kernel", "Intersect the full count kernel with the literal original b-zero kernel. The result is exactly the line of ket {1}. Original Lean signature: theorem relative_kernel : LinearMap.ker M \u2293 LinearMap.ker (b 0) =\n    Submodule.span \u2102 ({ket {1}} : Set Fock)"),
                Node("c1vac", "The named relative ground is the original c at one applied to the original empty vacuum. Original Lean signature: def c1vac : Fock", DescribeRole.Definition),
                Node("c1vac_eq", "The original mode-vacuum formula identifies this state with ket {1}; it is not the empty occupation vacuum. Original Lean signature: theorem c1vac_eq : c1vac = ket {1}"),
                Node("relative_kernel_c1vac", "The literal joint kernel is exactly the complex multiples of the named original c-one vacuum. Original Lean signature: theorem relative_kernel_c1vac (v : Fock) :\n    (M v = 0 \u2227 b 0 v = 0) \u2194 \u2203 a : \u2102, v = a \u2022 c1vac"),
                Node("relative_eigenvalue_iff", "The algebraic point spectrum is exactly the natural numbers, even when the nonzero witnessing state must satisfy the literal relative b-zero condition. Original Lean signature: theorem relative_eigenvalue_iff (z : \u2102) :\n    (\u2203 v : Fock, v \u2260 0 \u2227 b 0 v = 0 \u2227 M v = z \u2022 v) \u2194\n      \u2203 q : \u2115, z = (q : \u2102)"),
                Node("eigenvalue_iff", "The full algebraic point spectrum is exactly the natural numbers. This is not a topological spectral theorem for a Hilbert completion. Original Lean signature: theorem eigenvalue_iff (z : \u2102) :\n    (\u2203 v : Fock, v \u2260 0 \u2227 M v = z \u2022 v) \u2194 \u2203 q : \u2115, z = (q : \u2102)"),
                Node("M_create_regular", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem M_create_regular (j : \u2115) (hj1 : j \u2260 1) (hj3 : j \u2260 3) :\n    M * create j - create j * M = create j"),
                Node("M_annihilate_regular", "This original-carrier identity is used in the finite occupation, coefficient, projection or mode calculation; its original telescope and conclusion are recorded below and bound to the native declaration in the evidence bundle. Original Lean signature: theorem M_annihilate_regular (j : \u2115) (hj1 : j \u2260 1) (hj3 : j \u2260 3) :\n    M * annihilate j - annihilate j * M = -annihilate j"),
